// Normalize input from any channel into standard format
const input = $input.item.json;
let normalized = {
  channel: 'unknown',
  sender_id: null,
  sender_name: null,
  message_text: '',
  message_type: 'text',
  voice_file_id: null,
  is_callback: false,
  callback_data: null,
  raw_data: input
};

// Telegram message
if (input.message?.text) {
  normalized.channel = 'telegram';
  normalized.sender_id = String(input.message.chat.id);
  normalized.sender_name = input.message.from?.first_name || 'Guest';
  normalized.message_text = input.message.text;
  normalized.message_type = 'text';
}
// Telegram voice message
else if (input.message?.voice) {
  normalized.channel = 'telegram';
  normalized.sender_id = String(input.message.chat.id);
  normalized.sender_name = input.message.from?.first_name || 'Guest';
  normalized.message_text = '[voice message - transcribing...]';
  normalized.message_type = 'voice';
  normalized.voice_file_id = input.message.voice.file_id;
}
// Telegram photo
else if (input.message?.photo) {
  normalized.channel = 'telegram';
  normalized.sender_id = String(input.message.chat.id);
  normalized.sender_name = input.message.from?.first_name || 'Guest';
  normalized.message_text = '[image received]';
  normalized.message_type = 'image';
}
// Telegram callback
else if (input.callback_query) {
  normalized.channel = 'telegram';
  normalized.sender_id = String(input.callback_query.message.chat.id);
  normalized.sender_name = input.callback_query.from?.first_name || 'Guest';
  normalized.is_callback = true;
  normalized.callback_data = input.callback_query.data;
  normalized.message_text = input.callback_query.data;
}
// WhatsApp
else if (input.entry?.[0]?.changes?.[0]?.value?.messages?.[0]) {
  const msg = input.entry[0].changes[0].value.messages[0];
  const contact = input.entry[0].changes[0].value.contacts?.[0];
  normalized.channel = 'whatsapp';
  normalized.sender_id = msg.from;
  normalized.sender_name = contact?.profile?.name || 'Guest';
  normalized.message_text = msg.text?.body || msg.interactive?.button_reply?.title || '';
  normalized.message_type = msg.type || 'text';
  normalized.is_callback = !!msg.interactive;
  normalized.callback_data = msg.interactive?.button_reply?.id || null;
}
// Twilio SMS
else if (input.Body && input.From) {
  normalized.channel = 'sms';
  normalized.sender_id = input.From;
  normalized.sender_name = 'Guest';
  normalized.message_text = input.Body;
}

normalized.timestamp = new Date().toISOString();
normalized.delay_seconds = Math.floor(Math.random() * 6) + 3;
return normalized;

parameters.text:
You are an intelligent message router for a vacation rental management system.

Analyze this incoming message and determine the appropriate action:

Message: {{ $('Normalize Input').item.json.message_text }}
Sender: {{ $('Normalize Input').item.json.sender_name }}
Channel: {{ $('Normalize Input').item.json.channel }}
Is Callback: {{ $('Normalize Input').item.json.is_callback }}
Existing Context: {{ $json.conversation_stage || 'none' }}

Classify into ONE of these categories:
1. BOOKING_INQUIRY - Questions about availability, pricing, or making a reservation
2. BOOKING_FOLLOWUP - Continuing an existing booking conversation
3. PAYMENT_RELATED - Payment questions, confirmation, issues
4. PROPERTY_QUESTION - Questions about property amenities, location, rules
5. MAINTENANCE_REPORT - Guest reporting an issue or problem
6. CHECK_IN_OUT - Arrival instructions, key codes, checkout questions
7. EMERGENCY - Urgent safety or security issue
8. OWNER_ACTION - Property owner managing their listing
9. GENERAL_GREETING - Hello, hi, general conversation start
10. UNKNOWN - Cannot determine intent

Respond with ONLY a JSON object:
{
  "category": "CATEGORY_NAME",
  "confidence": 0.0-1.0,
  "extracted_data": {
    "dates": null,
    "property_id": null,
    "issue_type": null
  },
  "suggested_response": "Brief friendly response if you can provide one"
}

