// Parse AI Router response and prepare routing
const normalized = $('Normalize Input').item.json;
const context = $('Get Conversation Context').item.json;
let aiResult;

try {
  aiResult = typeof $json.text === 'string' ? JSON.parse($json.text) : $json;
} catch (e) {
  aiResult = { category: 'UNKNOWN', confidence: 0.5 };
}

// Determine which workflow to call
const routingMap = {
  'BOOKING_INQUIRY': 'WF2_AI_Booking_Agent',
  'BOOKING_FOLLOWUP': 'WF2_AI_Booking_Agent',
  'PAYMENT_RELATED': 'WF4_Payment_Processor',
  'PROPERTY_QUESTION': 'WF2_AI_Booking_Agent',
  'MAINTENANCE_REPORT': 'WF5_Property_Operations',
  'CHECK_IN_OUT': 'WF2_AI_Booking_Agent',
  'EMERGENCY': 'WF8_Safety_Screening',
  'OWNER_ACTION': 'WF5_Property_Operations',
  'GENERAL_GREETING': 'WF2_AI_Booking_Agent',
  'UNKNOWN': 'WF2_AI_Booking_Agent'
};

return {
  // Routing info
  target_workflow: routingMap[aiResult.category] || 'WF2_AI_Booking_Agent',
  category: aiResult.category,
  confidence: aiResult.confidence,

  // Pass through data
  channel: normalized.channel,
  sender_id: normalized.sender_id,
  sender_name: normalized.sender_name,
  message_text: normalized.message_text,
  is_callback: normalized.is_callback,
  callback_data: normalized.callback_data,

  // Context
  conversation_id: context.conversation_id || null,
  property_id: context.property_id || aiResult.extracted_data?.property_id || null,
  conversation_stage: context.conversation_stage || 'new',

  // AI suggestions
  extracted_data: aiResult.extracted_data || {},
  suggested_response: aiResult.suggested_response || null,

  timestamp: new Date().toISOString()
};

// Merge transcription result back into the normalized message
const transcription = $input.item.json;
const originalData = $('Normalize Input').item.json;
return {
  ...originalData,
  message_text: transcription.text || '[could not transcribe voice]',
  message_type: 'voice_transcribed'
};
